import{_ as l,l as i,o,c as t,v as e,p as s,x as n,d as u,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Voronoi 与 Delaunay","description":"","frontmatter":{"title":"Voronoi 与 Delaunay","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/voronoi-delaunay.md","filePath":"cs/voronoi-delaunay.md","lastUpdated":1789023840000}'),h={name:"cs/voronoi-delaunay.md"};function c(_,a,D,m,f,y){const r=i("Mermaid");return o(),t("div",null,[a[1]||(a[1]=e('<h1 id="voronoi-与-delaunay" tabindex="-1">Voronoi 与 Delaunay <a class="header-anchor" href="#voronoi-与-delaunay" aria-label="Permalink to &quot;Voronoi 与 Delaunay&quot;">​</a></h1><div class="epigraph"><p>Voronoi 胞是距站点最近的区域；对偶是 Delaunay 三角剖分：空圆，最大化最小角。</p><footer>—— 据 Fortune, A Sweepline Algorithm for Voronoi Diagrams, 1987；Delaunay, 1934；CLRS 第 33 章整理</footer></div><p>上一课<a href="/cs/half-plane-intersection">半平面交</a>给凸可行域。对每个站点 \\(p_i\\)，胞 \\(\\{x:\\|x-p_i\\|\\le\\|x-p_j\\|\\}\\) 是半平面交。缺口是整体图：Voronoi 图与 Delaunay 三角。Fortune 扫描 \\(O(n\\log n)\\)。不重写单个半平面交。后课点定位用这些剖分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Delaunay：若三角形外接圆不含其它站点（一般位置）。对偶边：Voronoi 邻接 \\(\\Leftrightarrow\\) Delaunay 边。性质：最大最小角；最近邻在 Delaunay 边上。欧氏 MST 是 Delaunay 子图。</p><p>缺口是对偶结构，不是再求 \\(n\\) 次半平面。</p><h3 id="不是-k-nn-机器学习课" tabindex="-1">不是 k-NN 机器学习课 <a class="header-anchor" href="#不是-k-nn-机器学习课" aria-label="Permalink to &quot;不是 k-NN 机器学习课&quot;">​</a></h3><p>几何最近邻图。高维 Voronoi 爆炸。本课平面。</p><p><span class="marginnote">Fortune 1987 海滩线。Delaunay 1934。后课点定位：Kirkpatrick 或梯形图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Fortune：扫描线 + 海滩抛物线，事件为站点与圆（顶点）。或增量翻边（Lawson）从任意三角到 Delaunay。输出边表。</p>',11)),(o(),s(p,null,{default:n(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%AB%99%E7%82%B9%22%5D%20--%3E%20VOR%5B%22Voronoi%20%E8%83%9E%22%5D%0A%20%20VOR%20--%3E%20DEL%5B%22Delaunay%20%E5%AF%B9%E5%81%B6%22%5D%0A%20%20DEL%20--%3E%20MST%5B%22%E5%90%AB%E6%AC%A7%E6%B0%8F%20MST%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>一般位置：无四点共圆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空圆 \\(\\Leftrightarrow\\) 对偶边。海滩线是扫描下的抛物线包络，断点轨迹即 Voronoi 边。与凸包：最外 Delaunay 是凸包。与最近点对：Delaunay 含最近点边。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写高阶 Voronoi。加权/功率图点名。后课默认：平面 Voronoi/Delaunay \\(O(n\\log n)\\)。下一课点定位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Voronoi 最近区域；Delaunay 空圆三角。</li><li>对偶；含 MST 与最近邻边。</li><li>Fortune 扫描 \\(O(n\\log n)\\)。</li><li>出处：Fortune, 1987；Delaunay, 1934。</li></ul>',7))])}const k=l(h,[["render",c]]);export{T as __pageData,k as default};
